from abc import abstractmethod, ABCMeta
import subprocess


class Executor(object):
    """Base class for All shell command executions"""

    __metaclass__ = ABCMeta

    @abstractmethod
    def execute_command_on_secgw(self, command):
        """ Runs the given command on secgw and returns its output """

    def execute_command_locally(self, command):
        """ Runs the given command on the virtual machine """
        return subprocess.check_output(command, shell=True)

    @staticmethod
    def create(sec_gw_ip):
        """Returns Executor local if secgw is on virtual machine or Executor remote if secgw is on a remote machine"""
        if sec_gw_ip == '127.0.0.1':
            return ExecutorLocal()
        else:
            return ExecutorRemote(sec_gw_ip)


class ExecutorLocal(Executor):
    """ All  shell commands execution on local machine handled in this class"""

    def execute_command_on_secgw(self, command):
        """Executes command on secgw"""
        return self.execute_command_locally(command)


class ExecutorRemote(Executor):
    """ All  shell commands execution on remote machine handled in this class"""

    def __init__(self, sec_gw_ip):
        self.sec_gw_ip = sec_gw_ip

    def execute_command_on_secgw(self, cmd):
        """Executes command on secgw"""
        ssh_cmd_template = 'sshpass -p {pwd} ssh {user}@{ip} "{cmd}"'
        ssh_command = ssh_cmd_template.format(pwd='ute', user='ute', ip=self.sec_gw_ip, cmd=cmd)
        return self.execute_command_locally(ssh_command)
